<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantTermsOfUse\Domain\ValueObject\Accessor\TenantTermsOfUseTextAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantTermsOfUseTextAccessor trait.
 *
 * Covers null default, string/VO assignment via withText,
 * getText/text accessors, and isTextChanged with/without original.
 */
class TenantTermsOfUseTextAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withText creates a new instance with the Text set
     * from a string value, and getText returns the primitive string.
     */
    public function testWithTextFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantTermsOfUseTextAccessorUnitTest();

        // Act
        $result = $holder->withText('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getText());
    }
    /**
     * Asserts that withtext has access to the value object
     * from a string value, and getText returns the primitive string.
     */
    public function testWithTextFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantTermsOfUseTextAccessorUnitTest();

        // Act
        $result = $holder->withText('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->text()->value());
    }
    public function testChangedText(): void
    {
        // Arrange
        $holder = new ImplWithTenantTermsOfUseTextAccessorUnitTest()->withText('one');
        $original = $holder->withText('one');
        $same = $holder->withText('one');
        $modified = $holder->withText('other');

        // Act
        $withSame = $original->isTextChanged($same);
        $withDiferent = $original->isTextChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantTermsOfUseTextAccessorUnitTest
{
    use TenantTermsOfUseTextAccessor;
}
